import{z as d,x as p,o as t,c as A,q as n,j as l,D as r,d as e,s as E,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"证明助手与依值类型直觉","description":"","frontmatter":{"title":"证明助手与依值类型直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/proof-assistants.md","filePath":"cs/proof-assistants.md","lastUpdated":1791063341000}'),B={name:"cs/proof-assistants.md"};function m(h,a,f,u,T,c){const o=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=n('<h1 id="证明助手与依值类型直觉" tabindex="-1">证明助手与依值类型直觉 <a class="header-anchor" href="#证明助手与依值类型直觉" aria-label="Permalink to &quot;证明助手与依值类型直觉&quot;">​</a></h1><div class="epigraph"><p>Curry–Howard：证明即程序，命题即类型。依值类型让类型依赖值，等式可在类型里出现。助手检查推导；人仍要给不变式与策略。计算理论补层在此封口。</p><footer>—— 据 Martin-Löf；Howard；The Univalent Foundations Program, Homotopy Type Theory 整理</footer></div><p>上一课<a href="/cs/smt-solver">SMT</a> 自动但碎片化，失败时给模型不给可搬运的证明对象。缺口是<strong>交互证明助手</strong>：Coq、Lean、Isabelle。本课直觉：类型 = 命题，项 = 证明；依值类型为何能写「长度为 \\(n\\) 的向量」。不教安装，不重写 λ 课的 β。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>简单类型 λ 对应直觉主义命题：\\(\\to\\) 是函数。要证 \\(\\forall n,\\ldots\\) 需要依值：\\(\\Pi n:\\mathbb{N}.\\,P(n)\\)。等式类型 \\(a=b\\) 的证明是同一化或改写。助手核：类型检查可判定（或可检查），信任基小。策略（tactic）生成项，核再验。相对 SMT：这里证明是一等对象，可抽取程序；代价是人写。</p><p><a href="/cs/natural-deduction">自然演绎</a> 的引入消去正是类型构造子/消去子。Hoare 三元组可内嵌为类型，或另做验证条件再 SMT——两条路可混（why3）。</p><h3 id="不是「ai-写完证明」" tabindex="-1">不是「AI 写完证明」 <a class="header-anchor" href="#不是「ai-写完证明」" aria-label="Permalink to &quot;不是「AI 写完证明」&quot;">​</a></h3><p>自动策略、 hammers 会调用 SMT，但仍要类型正确。不可判定的一阶碎片不会因依值类型变可判定；人选择归纳与引理。</p><p><span class="marginnote">Howard 1969 笔记；Martin-Löf 类型论。Coq/Lean 实现 CIC 变体。HoTT 书是同伦视角，本课不进路径类型。Isabelle/HOL 是简单类型高阶逻辑，另一风格，点名。</span></p><p><span class="marginnote">「策略（tactic）」可以翻译成「解题套路」：你告诉它「用归纳法在 \\(n\\) 上拆」「先化简两边」，它替你把推导的中间步骤写成依值项。套路写错了最多失败重来，不会污染结论——因为最终要过核那一关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用「偶数 + 偶数 = 偶数」的归纳形状对照自然演绎 \\(\\forall\\) 引入。指出：终止检查对应完全正确；允许非终止则逻辑崩溃（\\(Y\\) 无类型）。对照<a href="/cs/recursion-theorem">递归定理</a>：助手里一般禁止无类型自应用。</p>',12)),(t(),l(i,null,{default:r(()=>[E(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROP%5B%22%E5%91%BD%E9%A2%98%22%5D%20--%3E%20TY%5B%22%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20PF%5B%22%E8%AF%81%E6%98%8E%22%5D%20--%3E%20TM%5B%22%E4%BE%9D%E5%80%BC%E9%A1%B9%22%5D%0A%20%20TM%20--%3E%20KER%5B%22%E6%A0%B8%E7%B1%BB%E5%9E%8B%E6%A3%80%E6%9F%A5%22%5D%0A%20%20SMT%5B%22SMT%22%5D%20-.-%3E%20TAC%5B%22%E7%AD%96%E7%95%A5%E5%8F%AF%E8%B0%83%E7%94%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[e("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,[e("计算理论课程收束：自动机到 TM，可计算与复杂，信息与数论，最后逻辑把「证明」连回程序。主干系统栈在"),s("a",{href:"/cs/to-systems-boundary"},"边界"),e(" 已封；本补层不重开 OS。后课若有附录文献，不插入这条课序。")],-1)),a[5]||(a[5]=s("p",null,"抽取：构造性证明可变成程序；经典排中律抽取需额外机制。",-1)),a[6]||(a[6]=s("p",null,[e("宇宙层级避免 Russell。归纳类型同时给出构造与消去（递归）。抽取到 OCaml/Haskell 把计算部分变成程序，证明部分擦掉。Isabelle/HOL 用简单类型 + 高阶逻辑，自动化强、依值弱。本补层封口：主干系统栈已在"),s("a",{href:"/cs/to-systems-boundary"},"边界"),e(" 结束，计算理论课序不重开 OS。")],-1)),(t(),l(i,null,{default:r(()=>[E(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%9E%84%E9%80%A0%E6%80%A7%E8%AF%81%E6%98%8E%20%E4%BE%9D%E5%80%BC%E9%A1%B9%22%5D%20--%3E%20K%5B%22%E6%A0%B8%E7%B1%BB%E5%9E%8B%E6%A3%80%E6%9F%A5%E9%80%9A%E8%BF%87%22%5D%0A%20%20K%20--%3E%20E%5B%22%E6%8A%BD%E5%8F%96%E5%99%A8%22%5D%0A%20%20E%20--%3E%20C%5B%22%E5%8F%AF%E8%BF%90%E8%A1%8C%E7%A8%8B%E5%BA%8F%20%E5%8F%AA%E7%95%99%E8%AE%A1%E7%AE%97%22%5D%0A%20%20K%20-.%E5%90%AB%E7%BB%8F%E5%85%B8%E5%85%AC%E7%90%86%E5%A6%82%E6%8E%92%E4%B8%AD%E5%BE%8B.-%3E%20X%5B%22%E9%9C%80%E9%A2%9D%E5%A4%96%E6%9C%BA%E5%88%B6%E6%89%8D%E5%8F%AF%E6%8A%BD%E5%8F%96%22%5D%0A%20%20X%20-.-%3E%20C%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">上图回答「证明怎么变成能跑的程序」：只有构造性证明能走抽取这条路，产出的代码里逻辑外壳被擦掉，留下的全是计算部分；用了排中律这类经典公理的证明，抽取要另配机制。</span></p><p><span class="marginnote">初学者容易以为抽取出的程序「自带正确性证明」。实际上证明在抽取时被丢掉了，正确性是「曾经被核验证过」这一历史事实；程序本身只是那个计算对象，不会再向读者解释自己。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CIC 的全体宇宙规则，不引入立方类型论。不把形式化数学库当作业清单。补层「计算理论」到此结束：后课默认，证明助手是检查依值项的核，与 SMT 互补而非替代。</p><p>核检查依值项，策略可调用 SMT，证明仍是一等对象。Curry–Howard 把自然演绎接回程序。计算理论补层封口，不重开已在系统边界结束的主干栈。</p><p><span class="marginnote">「信任基小」的意思：整个系统里只有核这一个部件需要你无条件相信，它做的事只有一条——逐条检查类型。策略、库、自动化再怎么出错，最坏也只是「证不出来」，不会让错误结论混过检查。就像考试可以打草稿，但判分只看卷面上的推导。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Curry–Howard：命题–类型，证明–程序。</li><li>依值类型表达依赖值的规范；核小、策略大。</li><li>与 SMT 分工：可搬运证明 vs 自动判定碎片。</li><li>出处：Martin-Löf；Howard；Coq/Lean 与 HoTT 文献。</li></ul>',8))])}const b=d(B,[["render",m]]);export{C as __pageData,b as default};
